-- Read-only login for the online Streamlit app.
-- Run in a Snowsight worksheet as ACCOUNTADMIN, after 00_setup.sql.
-- The app can only SELECT from GOLD, ML and SEEDS. It can't change anything.
USE ROLE ACCOUNTADMIN;

CREATE ROLE IF NOT EXISTS CT_APP_READER;
GRANT USAGE ON WAREHOUSE CT_WH TO ROLE CT_APP_READER;
GRANT USAGE ON DATABASE CASH_TRANSFER TO ROLE CT_APP_READER;

GRANT USAGE ON SCHEMA CASH_TRANSFER.GOLD  TO ROLE CT_APP_READER;
GRANT USAGE ON SCHEMA CASH_TRANSFER.ML    TO ROLE CT_APP_READER;
GRANT USAGE ON SCHEMA CASH_TRANSFER.SEEDS TO ROLE CT_APP_READER;

GRANT SELECT ON ALL TABLES IN SCHEMA CASH_TRANSFER.GOLD  TO ROLE CT_APP_READER;
GRANT SELECT ON ALL TABLES IN SCHEMA CASH_TRANSFER.ML    TO ROLE CT_APP_READER;
GRANT SELECT ON ALL TABLES IN SCHEMA CASH_TRANSFER.SEEDS TO ROLE CT_APP_READER;
-- dbt and the analysis recreate their tables, so also cover tables made later
GRANT SELECT ON FUTURE TABLES IN SCHEMA CASH_TRANSFER.GOLD  TO ROLE CT_APP_READER;
GRANT SELECT ON FUTURE TABLES IN SCHEMA CASH_TRANSFER.ML    TO ROLE CT_APP_READER;
GRANT SELECT ON FUTURE TABLES IN SCHEMA CASH_TRANSFER.SEEDS TO ROLE CT_APP_READER;

CREATE USER IF NOT EXISTS CT_APP
  TYPE = SERVICE
  DEFAULT_ROLE = CT_APP_READER
  DEFAULT_WAREHOUSE = CT_WH
  RSA_PUBLIC_KEY = '';
GRANT ROLE CT_APP_READER TO USER CT_APP;

SHOW GRANTS TO ROLE CT_APP_READER;
